  "scenario_id": "sf28712899f",
  "rule": "energy_bound",
  "explanation": "Single body falls onto arena floor with gravity 9.81. Before impact at step 90 speed 18.34 down, energy 176.07J. At step 91 body is placed on floor y=r and velocity reversed to 28.96 up (step 91), yielding energy 427.2J > allowed 198.68J (E0 176.07). Restitution e=0.5 should reduce speed to ~9 m/s, instead speed increases, injecting ~251J. Same occurs with e=0 (203.5J). Indicates floor collision resolution adds kinetic energy (positional correction / impulse sign error) rather than dissipating.",
  "citations": [
    {"step": 90, "body": 0, "field": "speed", "value": 18.343878071600283, "claim": "pre-impact downward speed"},
    {"step": 90, "body": -1, "field": "energy", "value": 176.07622921958583, "claim": "energy before impact within allowance"},
    {"step": 91, "body": 0, "field": "speed", "value": 28.962326514763358, "claim": "post-bounce upward speed larger than pre-impact despite e=0.5"},
    {"step": 91, "body": -1, "field": "energy", "value": 427.20269661739007, "claim": "first violation step, energy exceeds limit"}
  ],
  "counterfactual": {
    "scenario_id": "s60be3d1abc",
